pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 valFirst, uint256 valSecond) internal {
        uint beforeVal = valFirst;
        try c.SetMinSum(valFirst) {} catch { return; }
        bool reverted;
        try c.SetMinSum(valSecond) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterVal;
        try c.MinSum() returns (uint256 __r) { afterVal = __r; } catch { return; }
        assertTrue(reverted ? afterVal == beforeVal : afterVal == valSecond);
    }

    function testFuzz_run(uint256 valFirst, uint256 valSecond) public {
        _run(valFirst, valSecond);
    }

    receive() external payable {}
}
